@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 222 47% 6%;
    --foreground: 210 40% 98%;

    --card: 222 47% 8%;
    --card-foreground: 210 40% 98%;

    --popover: 222 47% 8%;
    --popover-foreground: 210 40% 98%;

    --primary: 187 92% 50%;
    --primary-foreground: 222 47% 6%;

    --secondary: 217 33% 17%;
    --secondary-foreground: 210 40% 98%;

    --muted: 217 33% 17%;
    --muted-foreground: 215 20% 65%;

    --accent: 263 70% 60%;
    --accent-foreground: 210 40% 98%;

    --destructive: 0 84% 60%;
    --destructive-foreground: 210 40% 98%;

    --border: 217 33% 17%;
    --input: 217 33% 17%;
    --ring: 187 92% 50%;

    --radius: 0.75rem;

    /* Custom tokens */
    --glow: 187 92% 60%;
    --surface: 222 47% 10%;
    --surface-hover: 222 47% 14%;

    /* Gradients */
    --gradient-primary: linear-gradient(135deg, hsl(187 92% 50%), hsl(263 70% 60%));
    --gradient-card: linear-gradient(145deg, hsl(222 47% 10%), hsl(222 47% 6%));
    --gradient-glow: radial-gradient(ellipse at center, hsl(187 92% 50% / 0.15), transparent 70%);
  }
}

@layer components {
  .glass {
    @apply bg-card/60 backdrop-blur-xl border border-border/50;
  }

  .glass-strong {
    @apply bg-card/80 backdrop-blur-2xl border border-border/60;
  }

  .glow-primary {
    box-shadow: 0 0 40px hsl(var(--primary) / 0.3), 0 0 80px hsl(var(--primary) / 0.1);
  }

  .glow-accent {
    box-shadow: 0 0 40px hsl(var(--accent) / 0.3), 0 0 80px hsl(var(--accent) / 0.1);
  }

  .text-gradient {
    @apply bg-clip-text text-transparent;
    background-image: var(--gradient-primary);
  }

  .btn-glow {
    @apply relative overflow-hidden;
  }

  .btn-glow::before {
    content: '';
    @apply absolute inset-0 opacity-0 transition-opacity duration-300;
    background: var(--gradient-primary);
    filter: blur(20px);
  }

  .btn-glow:hover::before {
    @apply opacity-50;
  }

  .upload-zone {
    @apply border-2 border-dashed border-border/50 rounded-2xl transition-all duration-300;
  }

  .upload-zone:hover {
    @apply border-primary/50 bg-primary/5;
  }

  .outfit-card {
    @apply relative overflow-hidden rounded-xl transition-all duration-300 cursor-pointer;
  }

  .outfit-card:hover {
    @apply scale-105;
    box-shadow: 0 20px 40px hsl(var(--primary) / 0.2);
  }

  .outfit-card.selected {
    @apply ring-2 ring-primary ring-offset-2 ring-offset-background;
  }
}

@layer utilities {
  .animate-float {
    animation: float 6s ease-in-out infinite;
  }

  .animate-pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite;
  }

  .animate-shimmer {
    animation: shimmer 2s linear infinite;
    background-size: 200% 100%;
  }
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-20px); }
}

@keyframes pulse-glow {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

@keyframes shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

body {
  @apply bg-background text-foreground antialiased;
  font-family: 'Inter', system-ui, sans-serif;
}

